const LINKS_SVG = `<g class="eug-link eug-link--gdpr"><path class="eug-link__line" d="M190.0 100.0Q252.7 309.0 425.0 442.8"/><circle class="eug-link__end" cx="425.0" cy="442.8" r="8"/></g><g class="eug-link eug-link--act"><path class="eug-link__line" d="M620.0 468.0Q540.3 564.9 451.4 476.3"/><circle class="eug-link__end" cx="451.4" cy="476.3" r="8"/></g><g class="eug-link eug-link--dec"><path class="eug-link__line" d="M180.0 734.0Q261.7 554.1 425.0 442.8"/><circle class="eug-link__end" cx="425.0" cy="442.8" r="8"/></g>`;

const DEFAULT_CARDS = [
  { id: 'gdpr', name: 'GDPR',                ref: 'Regulation (EU) 2016/679' },
  { id: 'act',  name: 'EU AI Act',           ref: 'Regulation (EU) 2024/1689' },
  { id: 'dec',  name: 'Commission Decision', ref: '(EU) 2026/713' },
];

const ICONS: Record<string, ReactNode> = {
  gdpr: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round">
      <circle cx="12" cy="12" r="8.6" />
      <path d="M3.4 12h17.2" />
      <path d="M12 3.4a13 13 0 0 1 0 17.2 13 13 0 0 1 0-17.2Z" />
    </svg>
  ),
  act: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7"
         strokeLinecap="round" strokeLinejoin="round">
      <path d="M12 4.2v16.4" />
      <path d="M8.2 20.6h7.6" />
      <path d="M4.4 7.4 20 5.6" />
      <path d="M12 5.4 4.4 7.4l-2.3 5.1a3.3 3.3 0 0 0 4.6 0L4.4 7.4Z" />
      <path d="m19.6 5.6-2.3 5.1a3.3 3.3 0 0 0 4.6 0L19.6 5.6Z" />
    </svg>
  ),
  dec: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7"
         strokeLinecap="round" strokeLinejoin="round">
      <path d="M14.2 3H7.4A1.4 1.4 0 0 0 6 4.4v15.2A1.4 1.4 0 0 0 7.4 21h9.2a1.4 1.4 0 0 0 1.4-1.4V7.2Z" />
      <path d="M14 3.2V7.4h4.2" />
      <path d="M9 12.6h6" />
      <path d="M9 16.2h4" />
    </svg>
  ),
};

type Card = { id: string; name: string; ref: string };

type Props = {
  size?: string;
  cards?: Card[];
  className?: string;
};

export default function EuRegulatoryGlobe({
  size = 'min(680px, 100%)',
  cards = DEFAULT_CARDS,
  className = '',
}: Props) {
  const rootRef = useRef<HTMLElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);

  // state, not classList: a re-render from above would drop the class and every layer is opacity 0 without it
  const [live, setLive] = useState(false);

  useEffect(() => {
    const root = rootRef.current;
    const stage = stageRef.current;
    if (!root) return;

    // each tether measures itself so it can draw at any size
    root.querySelectorAll<SVGPathElement>('.eug-link__line').forEach((p, i) => {
      p.style.setProperty('--len', String(Math.ceil(p.getTotalLength())));
      p.parentElement?.style.setProperty('--lin', i * 7 + 's');
    });

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setLive(true);
      root.querySelectorAll('svg').forEach((s) => s.pauseAnimations());
      return;
    }

    // start the load sequence only once the element is actually on screen
    let observer: IntersectionObserver | undefined;
    if ('IntersectionObserver' in window) {
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((e) => {
            if (e.isIntersecting) {
              setLive(true);
              observer?.disconnect();
            }
          });
        },
        { threshold: 0.25 }
      );
      observer.observe(root);
    } else {
      setLive(true);
    }

    // shallow pointer parallax, fine pointers only
    let raf = 0;
    let onMove: ((ev: PointerEvent) => void) | undefined;
    let onLeave: (() => void) | undefined;
    const fine = window.matchMedia('(hover:hover) and (pointer:fine)').matches;
    if (fine && stage) {
      onMove = (ev) => {
        if (raf) return;
        raf = requestAnimationFrame(() => {
          raf = 0;
          const r = root.getBoundingClientRect();
          stage.style.setProperty('--mx', ((ev.clientX - r.left) / r.width - 0.5).toFixed(3));
          stage.style.setProperty('--my', ((ev.clientY - r.top) / r.height - 0.5).toFixed(3));
        });
      };
      onLeave = () => {
        stage.style.setProperty('--mx', '0');
        stage.style.setProperty('--my', '0');
      };
      root.addEventListener('pointermove', onMove);
      root.addEventListener('pointerleave', onLeave);
    }

    return () => {
      observer?.disconnect();
      if (raf) cancelAnimationFrame(raf);
      if (onMove) root.removeEventListener('pointermove', onMove);
      if (onLeave) root.removeEventListener('pointerleave', onLeave);
    };
  }, []);

  const label =
    'Globe centred on Europe, marked with ' +
    cards.map((c) => c.name).join(', ') + '.';

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <noscript>
        <style dangerouslySetInnerHTML={{ __html: NOSCRIPT_CSS }} />
      </noscript>

      <figure
        ref={rootRef}
        className={`euglobe eug-armed ${live ? 'is-live' : ''} ${className}`.replace(/\s+/g, ' ').trim()}
        style={{ '--eug-size': size } as CSSProperties}
        role="img"
        aria-label={label}
      >
        <div className="euglobe__stage" ref={stageRef}>
          <svg
            className="euglobe__svg"
            viewBox="0 0 1000 1000"
            aria-hidden="true"
            dangerouslySetInnerHTML={{ __html: GLOBE_SVG }}
          />

          {cards.map((card) => (
            <div key={card.id} className={`euchip euchip--${card.id}`}>
              <span className="euchip__card">
                <span className="euchip__icon">{ICONS[card.id]}</span>
                <span className="euchip__text">
                  <span className="euchip__name">{card.name}</span>
                  <span className="euchip__ref">{card.ref}</span>
                </span>
              </span>
            </div>
          ))}

          {/* must stay a later sibling of the cards, the hover tethers use ~ */}
          <svg
            className="euglobe__links"
            viewBox="0 0 1000 1000"
            aria-hidden="true"
            dangerouslySetInnerHTML={{ __html: LINKS_SVG }}
          />
        </div>
      </figure>
    </>
  );
}
